/**
 * Finds two distinct indices in an array that add up to a target value.
 * 
 * @param {number[]} numbers - Array of numbers to search through
 * @param {number} target - The target sum
 * @returns {number[]} Array of two indices, or empty array if no solution exists
 * 
 * Input validation:
 * - If input is not an array, returns []
 * - If array has fewer than 2 elements, returns []
 * - If array contains non-number elements, they are ignored (skipped)
 * 
 * Deterministic rule for multiple solutions:
 * - Returns the first pair found in left-to-right order of the first element
 * - If multiple pairs have the same first element, returns the one with the smallest second index
 */
function twoSum(numbers, target) {
  // Input validation
  if (!Array.isArray(numbers) || numbers.length < 2) {
    return [];
  }

  const numMap = new Map();

  for (let i = 0; i < numbers.length; i++) {
    // Skip non-number elements
    if (typeof numbers[i] !== 'number') {
      continue;
    }

    const complement = target - numbers[i];

    if (numMap.has(complement)) {
      // Return the first valid pair found in left-to-right order
      return [numMap.get(complement), i];
    }

    // Store the current number with its index
    numMap.set(numbers[i], i);
  }

  // No solution found
  return [];
}
```

